<?php use Hls\Http\View as V; $type ??= 'text'; $value ??= ''; $required ??= false; $id ??= 'field-' . $name; ?>
<div class="form-field"><label for="<?= V::escape($id) ?>"><?= V::escape($label) ?><?= $required ? '<span class="required" aria-hidden="true"> *</span>' : '' ?></label>
<?php if ($type === 'select'): ?><select id="<?= V::escape($id) ?>" name="<?= V::escape($name) ?>" aria-label="<?= V::escape($label) ?>" <?= $required ? 'required' : '' ?>><?php foreach ($options as $option): ?><option value="<?= V::escape($option['id']) ?>" <?= (string)$value === (string)$option['id'] ? 'selected' : '' ?>><?= V::escape($option['name']) ?></option><?php endforeach ?></select>
<?php elseif ($type === 'textarea'): ?><textarea id="<?= V::escape($id) ?>" name="<?= V::escape($name) ?>" aria-label="<?= V::escape($label) ?>" rows="3" <?= isset($max) ? 'maxlength="' . (int)$max . '"' : '' ?>><?= V::escape($value) ?></textarea>
<?php else: ?><input id="<?= V::escape($id) ?>" name="<?= V::escape($name) ?>" aria-label="<?= V::escape($label) ?>" type="<?= V::escape($type) ?>" value="<?= $type === 'password' ? '' : V::escape($value) ?>" <?= $required ? 'required' : '' ?> <?= isset($max) ? 'maxlength="' . (int)$max . '"' : '' ?> <?= isset($min) ? 'minlength="' . (int)$min . '"' : '' ?> <?= isset($autocomplete) ? 'autocomplete="' . V::escape($autocomplete) . '"' : '' ?>><?php endif ?>
<?php if (isset($hint)): ?><small class="field-hint"><?= V::escape($hint) ?></small><?php endif ?><span class="field-error" id="<?= V::escape($id) ?>-error" hidden></span></div>
